'Wallet_Payment_Method_Missing' => 'Lompakon maksutapa puuttuu',
'Wallet_Payment_Method_Missing_Help' => 'Maksutapaa, jonka nimi on täsmälleen "Wallet", ei löytynyt. POS-lompakkomaksu tunnistetaan tällä nimellä, joten asiakkaat eivät voi maksaa lompakollaan ennen kuin lisäät tänne maksutavan nimeltä "Wallet":',

'Show_Previous_Dues_Line' => 'Näytä aiemmat erääntyneet -rivi',
'Show_Previous_Dues_Line_Desc' => 'Saldo, jonka asiakas oli velkaa ennen tätä myyntiä. Tulostetaan vain, kun se on suurempi kuin nolla.',
'Show_Net_Balance_Line' => 'Näytä nettosaldo-rivi',
