'QZ_Tray_Printer' => 'QZ Tray (tulostin tällä tietokoneella)',
'QZ_Printer_Name_Hint' => 'Tulostimen nimi sellaisena kuin se näkyy QZ Trayta käyttävällä tietokoneella. Jätä tyhjäksi käyttääksesi kyseisen tietokoneen oletustulostinta. Napsauta ⟳ tunnistaaksesi tulostimet.',
'QZ_Not_Running' => 'QZ Tray ei ole käynnissä tällä tietokoneella. Asenna se osoitteesta qz.io ja pidä se käynnissä, ja salli sitten tämä sivusto, kun QZ kysyy.',
'Detect_Printers' => 'Tunnista tulostimet',
'QZ_Download_Cert' => 'Lataa varmenne (override.crt)',
'QZ_Setup_Title' => 'QZ Tray -tulostuksen määrittäminen (kerran, jokaisella tarroja tulostavalla tietokoneella)',
'QZ_Step_Install' => '1. Asenna QZ Tray tälle tietokoneelle — lataa se ilmaiseksi osoitteesta qz.io, käynnistä se ja jätä se käyntiin (se on Windowsissa ilmaisinalueella tai macOS:ssä valikkorivillä).',
'QZ_Step_Connect' => '2. Kytke tarratulostin USB:llä ja tarkista, että se on asennettu käyttöjärjestelmään (Windows: Asetukset > Tulostimet ja skannerit — macOS: Järjestelmäasetukset > Tulostimet ja skannerit).',
'QZ_Step_Detect' => '3. Napsauta yllä olevan "Tulostimen nimi" -kentän vieressä olevaa ⟳-painiketta tunnistaaksesi tämän tietokoneen tulostimet ja valitse sitten tarratulostimesi. Jätä kenttä tyhjäksi käyttääksesi tietokoneen oletustulostinta.',
'QZ_Step_Cert' => '4. Jotta tulostus onnistuu ilman lupaikkunaa, lataa alla oleva varmenne ja kopioi se QZ Trayn asennuskansioon nimellä override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Sulje sitten QZ Tray ja käynnistä se uudelleen.',
'QZ_Step_Test' => '5. Napsauta alla "Tulosta testitarra". Jos QZ Tray pyytää lupaa, napsauta Salli — kun varmenne on asennettu, se ei kysy uudelleen.',
'QZ_Step_Save' => '6. Tallenna nämä asetukset napsauttamalla Lähetä. Tulosta viivakoodi -sivun tarrat tulostuvat nyt suoraan tälle tulostimelle ilman selaimen tulostusikkunaa.',
'QZ_Setup_Note' => 'QZ Tray toimii tietokoneella, jolla selaat, joten tämä toimii, vaikka Stocky olisi etäpalvelimella. Jokaiseen tarroja tulostavaan tietokoneeseen on asennettava QZ Tray.',

