/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Tilausopas',
'Ord_Guide_Intro' => 'Miten verkkokauppasi tilaus siirtyy varastoosi ja kirjanpitoosi ja missä raha todellisuudessa kirjataan.',
'Ord_Guide_Lifecycle_Title' => 'Tilauksen tila',
'Ord_Guide_Lifecycle_Pending' => 'Uusi tilaus odottaa tarkistustasi. Vain odottavan tilauksen voi vahvistaa tai perua.',
'Ord_Guide_Lifecycle_Confirmed' => 'Hyväksyit tilauksen. Stocky luo myynnin valitsemaasi varastoon ja vähentää varastosaldoa — tämä myynti on tietue, josta varasto-, maksu- ja tulosraporttisi lukevat.',
'Ord_Guide_Lifecycle_Shipped' => 'Lähetit tilauksen. Vain toimitus: varastosaldo vähennettiin jo vahvistettaessa.',
'Ord_Guide_Lifecycle_Delivered' => 'Asiakas vastaanotti tilauksen. Tästä alkaa palautusaika.',
'Ord_Guide_Lifecycle_Cancelled' => 'Tilaus peruttiin ennen vahvistusta, joten myyntiä ei luotu eikä varastosaldoa vähennetty.',
'Ord_Guide_PaymentStatus_Tip' => 'Asetetaan kassalla, eikä sitä voi muokata tässä. Napsauta nähdäksesi, miten maksu kirjataan.',
'Ord_Guide_Payment_Title' => 'Maksun tila',
'Ord_Guide_Payment_Intro' => 'Tämä sarake kertoo, miten asiakas valitsi maksaa kassalla. Verkkokauppa asettaa sen, eikä sitä voi muokata tältä sivulta — itse rahaa seurataan myynnissä, jonka tilauksen vahvistaminen luo.',
'Ord_Guide_Payment_Paid' => 'Asiakas maksoi jo verkossa maksuyhdyskäytävän kautta. Tilauksen vahvistaminen luo myynnin tilaan Maksettu ja kirjaa maksun puolestasi — muuta ei tarvitse tehdä.',
'Ord_Guide_Payment_Pending' => 'Postiennakko, tilisiirto tai muu myöhemmin maksettava tapa. Tilauksen vahvistaminen luo myynnin tilaan Maksamaton, joten kirjaat rahan itse, kun olet saanut sen — katso alla olevat vaiheet.',
'Ord_Guide_Payment_Failed' => 'Maksuyhdyskäytävä hylkäsi maksun tai asiakas keskeytti sen. Tilaus perutaan automaattisesti.',
'Ord_Guide_MarkPaid_Title' => 'Maksun muuttaminen odottavasta maksetuksi',
'Ord_Guide_MarkPaid_Step1' => 'Vahvista tilaus ensin tässä — vahvistaminen luo myynnin.',
'Ord_Guide_MarkPaid_Step2' => 'Avaa Myynnit > Kaikki myynnit ja etsi kyseinen myynti (sama asiakas, ja tietosivu näyttää verkkotilauksen, josta se on peräisin).',
'Ord_Guide_MarkPaid_Step3' => 'Avaa rivin toimintovalikko ja valitse Luo maksu.',
'Ord_Guide_MarkPaid_Step4' => 'Syötä summa, maksutapa ja päivämäärä ja tallenna. Myynnin tila muuttuu itsestään tilaan Osittainen tai Maksettu summasta riippuen.',
'Ord_Guide_MarkPaid_Note' => 'Tässä näkyvä maksun tila kirjaa edelleen kassalla tehdyn valinnan ja pysyy ennallaan. Myynti on kirjanpidon tietue, ja se syöttää maksu- ja tulosraporttisi. Käytä myynnin Näytä maksut -toimintoa tarkastellaksesi tai muokataksesi syöttämiäsi tietoja.',
'Ord_Guide_Notes_Title' => 'Hyvä tietää',
'Ord_Guide_Note_Warehouse' => 'Vahvistettaessa valitsemasi varasto määrää, mistä varastosaldo otetaan. Varastot, jotka eivät kata koko tilausta, on merkitty luettelossa tilaan Loppu varastosta.',
'Ord_Guide_Note_Preorder' => 'Ennakkotilattavat nimikkeet ohittavat varastotarkistuksen, joten niitä sisältävä tilaus voidaan vahvistaa, vaikka määrää ei vielä olisi varastossa.',
'Ord_Guide_Note_Flagged' => 'Merkitty-tunniste tarkoittaa, että tilaus laukaisi petostarkistuksen kassalla. Vie osoitin tunnisteen päälle nähdäksesi syyn ja tarkista tilaus ennen vahvistamista.',
'Ord_Guide_Note_Cancel' => 'Peruminen on mahdollista vain, kun tilaus on vielä odottava. Kun se on vahvistettu, peruuta se myynnin tai asiakaspalautuksen kautta.',


