'VG_Opt_Step2' => 'Kirjoita vaihtoehdon nimi, kuten Väri tai Koko, tai valitse jokin ehdotuksista.',
'VG_Opt_Step3' => 'Kirjoita arvo (esimerkiksi Punainen) ja paina Enter. Toista jokaiselle arvolle; myös pilkku erottaa arvot. Poista arvo napsauttamalla sen x-merkkiä.',
'VG_Opt_Step4' => 'Napsauta "Lisää vaihtoehto" lisätäksesi toisen tai kolmannen vaihtoehdon (enintään 3 vaihtoehtoa).',
'VG_Opt_Step5' => 'Napsauta "Luo variantit". Jokaista yhdistelmää kohden luodaan yksi rivi, ja sen nimi muodostetaan automaattisesti, esimerkiksi "Red / S".',
'VG_Opt_Step6' => 'Syötä kustannus ja hinta jokaiselle riville tai kirjoita arvo kenttään "Käytä kaikkiin" ja napsauta Kustannus tai Hinta kopioidaksesi sen jokaiselle riville.',
'VG_Opt_Step7' => 'Koodit luodaan puolestasi. Kirjoita oma koodisi tai napsauta päivityskuvaketta luodaksesi uuden.',
'VG_Opt_Step8' => 'Valinnainen: valitse vaihtoehdolle "Värimallit" ja valitse väri kullekin arvolle; kauppa näyttää sen värillisenä pisteenä.',
'VG_Rows_Title' => 'Varianttirivit',
'VG_Rows_Text' => 'Jokaisella rivillä on kuva, koodi, viivakoodi, kustannus, hinta, tukkuhinta ja vähimmäismyyntihinta. Tuotetta luodessa voit myös syöttää alkusaldon varastoittain jokaiselle variantille. "Keskeneräinen"-tunniste tarkoittaa, että riviltä puuttuu arvo jollekin vaihtoehdolle.',
'VG_List_Title' => 'Yksinkertainen luettelotila',
'VG_List_Text' => 'Kirjoita variantin nimi ja paina Enter (tai napsauta Lisää) lisätäksesi rivin, ja täytä sitten sen koodi ja hinnat. Tämä on perinteinen toimintatapa, ja se on edelleen käytettävissä olemassa oleville tuotteille.',
'VG_Edit_Title' => 'Myöhempi muokkaus',
'VG_Edit_1' => 'Lisää arvo ja napsauta "Luo variantit": vain puuttuvat yhdistelmät lisätään. Olemassa olevat rivit säilyttävät koodinsa, hintansa ja historiansa.',
'VG_Edit_2' => 'Arvon tai vaihtoehdon poistaminen poistaa sitä käyttävät rivit. Jo tallennetut rivit poistetaan, kun tallennat tuotteen, vahvistuksen jälkeen.',
'VG_Edit_3' => 'Varianttia, jolla on vielä varastosaldoa, ei voi poistaa. Oikaise tai siirrä sen varastosaldo ensin.',
'VG_Edit_4' => 'Vaihtaminen "Yksinkertaiseen luetteloon" säilyttää rivit ja niiden nimet, mutta poistaa vaihtoehtojen määritelmät.',
'VG_Store_Title' => 'Verkkokaupassa',
'VG_Store_Text' => 'Asiakkaat valitsevat yhden arvon kustakin vaihtoehdosta, esimerkiksi ensin värin ja sitten koon. Yhdistelmät, joita ei ole olemassa, on poistettu käytöstä, ja loppuneet on yliviivattu. Valittu variantti lisätään ostoskoriin.',
'Choose_Source' => 'Valitse lähde',
'Portal_Request' => 'Portaalipyyntö',
'Portal_Quotation_Requests' => 'Portaalin tarjouspyynnöt',
'Warehouse_Invoice_Address_Help' => 'Tämän varaston myöntämiin laskuihin tulostettava katuosoite. Jätä tyhjäksi käyttääksesi asetusten yritysosoitetta.',
'Warehouse_Logo_Help' => 'Tämän varaston laskuihin ja POS-kuitteihin tulostettava logo. Jätä tyhjäksi käyttääksesi yrityksen logoa.',
'Warehouse_Invoice_Footer_Help' => 'Tämän varaston myöntämien laskujen alaosaan tulostettava lisähuomautus.',
'Issued_By' => 'Myöntäjä',
'Enable_Warehouse_Letterhead' => 'Varaston kirjelomake laskuissa',
'Enable_Warehouse_Letterhead_Hint' => 'Tulosta myöntävä varasto laskuihin, POS-kuitteihin ja julkiselle laskusivulle: sen nimi korvaa yrityksen nimen, ja sen osoite, puhelin, sähköposti, logo ja alatunnisteen huomautus korvaavat yrityksen vastaavat. Mikä tahansa varastossa tyhjäksi jätetty kenttä käyttää yleisiä yritysasetuksia.',
'Warehouse_Letterhead_Receipt_Notice' => 'Varaston kirjelomake on käytössä: oikeaan kuittiin tulostettu kaupan nimi, osoite ja puhelin tulevat myynnin myöntäneestä varastosta, ja sen alatunnisteen huomautus lisätään asiakkaan huomautuksen alle.',
