'Upd_Note_Code_Changes_Lost' => 'Huomautus 1: Jos olet tehnyt koodiin muutoksia käsin, muutoksesi menetetään.',
'Upd_Manual_Steps_Intro' => 'Päivitä sovelluksesi seuraavien vaiheiden mukaisesti',
'Upd_Note_Permission_Only' => 'Huomautus 2: vain ylläpitäjä tai käyttäjä, jolla on oikeus "{perm}", voi päivittää järjestelmän',
'Upd_Manual_Step_Backup_Db' => 'Ota varmuuskopio tietokannastasi. Siirry kohtaan {backup} ja napsauta Luo varmuuskopio – löydät sen kohteesta {path} – tai vie tietokantasi PhpMyAdminista ja tallenna se tietokoneellesi.',
'Upd_Manual_Step_Backup_Files' => 'Ota varmuuskopio tiedostoistasi ennen päivittämistä.',
'Upd_Manual_Step_Download' => 'Lataa uusin versio CodeCanyon-tililtäsi ja pura se.',
'Upd_Manual_Step_Remove' => 'Poista aiemmat tiedostot, {except}:',
'Upd_Except' => 'paitsi',
'Upd_File_Label' => 'tiedosto: {name}',
'Upd_Folder_Label' => 'kansio: {name}',
'Upd_Manual_Step_Reupload' => 'Lataa uuden päivityksen tiedostot ja kansiot uudelleen, {except} samat kolme yllä olevaa polkua.',
'Upd_Manual_Step_Visit' => 'Päivitä tietokantasi siirtymällä osoitteeseen {url}.',
'Upd_Manual_Step_Clear_Cache' => 'Tyhjennä selaimesi välimuisti perusteellisesti.',
'Upd_Manual_Step_Done' => 'Valmista! Nauti päivitetystä sovelluksesta.',
'Upd_Note_Blank_Pages' => 'Huomautus: Jos jotkin sivut eivät lataudu tai ovat tyhjiä, varmista, että olet tyhjentänyt selaimesi välimuistin.',
'Upd_Guide_Before_Title' => '1. Ennen päivittämistä',
'Upd_Guide_Before_Download' => 'Lataa sovelluksen {package} CodeCanyon-tililtäsi ({path}). Älä pura sitä – päivitystyökalu tarvitsee ZIP-tiedoston täsmälleen ladatussa muodossa.',
'Upd_Latest_Full_Zip' => 'uusin täysi ZIP-paketti',
'Upd_Guide_Before_Admin' => 'Varmista, että olet kirjautunut ylläpitäjänä, jolla on oikeus {perm}. Kukaan muu ei näe päivitystyökalua eikä voi käyttää sitä.',
'Upd_Guide_Before_Quiet' => 'Valitse hiljainen hetki: päivityksen aikana sovellus siirtyy hetkeksi huoltotilaan ja muut käyttäjät lukitaan ulos.',
'Upd_Guide_Before_No_Manual' => 'Sinun {not} tarvitse varmuuskopioida käsin, purkaa tiedostoja, suorittaa komentoja, muokata konfiguraatiotiedostoja tai koskea tietokantaan – päivitystyökalu tekee kaiken tämän automaattisesti. (Ylimääräinen manuaalinen varmuuskopio ei tietenkään koskaan haittaa.)',
'Upd_Not' => 'ei',
'Upd_Guide_Code_Overwritten' => 'Jos olet muokannut sovelluksen koodia käsin, päivitys korvaa muutoksesi. Datasi, latauksesi, asetuksesi ja .env säilytetään aina.',
'Upd_Guide_Running_Title' => '2. Päivityksen suorittaminen',
'Upd_Guide_Run_Open' => 'Avaa {path} (tämä sivu) ja pysy välilehdellä {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: napsauta tai vedä ladattu paketti latauslaatikkoon. Suuret tiedostot ladataan pieninä osina, joten tämä toimii myös jaetussa webhotellissa, jossa latausrajat ovat pienet. Tarkistussumma suojaa vioittuneilta tai keskeneräisiltä latauksilta.',
'Upd_Upload_The_Zip' => 'Lataa ZIP',
'Upd_Guide_Run_Validation' => '{auto} latauksen jälkeen (voit suorittaa sen uudelleen painikkeella {button}). Järjestelmä tarkistaa: ZIP-tiedoston eheyden, paketin rakenteen ja täydellisyyden, versioiden yhteensopivuuden (vanhempaan versioon palaaminen estetään), vaaditun PHP-version ja laajennukset, tiedostojen käyttöoikeudet, vapaan levytilan, tietokantayhteyden, konfiguraation sekä sen, ettei muuta päivitystä ole käynnissä.',
'Upd_Validation_Runs_Automatically' => 'Tarkistus suoritetaan automaattisesti',
'Upd_Guide_Run_Review' => 'Tarkastele paneelia {panel}. Painike {button} tulee näkyviin vasta, kun kaikki kriittiset tarkistukset menevät läpi. Jos tarkistus epäonnistuu, viesti kertoo tarkalleen, mitä korjata.',
'Upd_Guide_Run_Click' => 'Napsauta {button} ja vahvista. Sitten vain {keep} ja seuraa edistymispalkkia. Järjestelmä suorittaa järjestyksessä:',
'Upd_Keep_Page_Open' => 'pidä tämä sivu auki',
'Upd_Guide_Phase_Backup' => '{label} – luodaan täydellinen tietokantavedos, ZIP-arkisto jokaisesta sovellustiedostosta, jota päivitys voi muuttaa, sekä kopio tiedostosta {env}, ja ne {verified}. Päivitys ei koskaan koske latauksiisi ({images}) eikä kohteeseen {storage}, joten niitä ei arkistoida. Jos varmuuskopiota ei voida luoda, päivitys pysähtyy tähän eikä mitään muuteta.',
'Upd_Verified' => 'tarkistetaan',
'Upd_Guide_Phase_Prepare' => '{label} – uusi versio puretaan valmistelualueelle ja tarkistetaan uudelleen. Käytössä oleva sovellus on yhä koskematon.',
'Upd_Guide_Phase_Maintenance' => '{label} – huoltotila otetaan käyttöön; vierailijat näkevät ystävällisen "Palaamme pian" -näkymän.',
'Upd_Guide_Phase_Files' => '{label} – uudet tiedostot vaihdetaan käyttöön lähes välittömästi; vanhat tiedostot pidetään sivussa palautusta varten. Suojattuja polkuja ({env}, {storage}, {images}) ei koskaan korvata.',
'Upd_Guide_Phase_Database' => '{label} – migraatiot suoritetaan, minkä jälkeen käyttöoikeudet, käännökset ja pohjat päivitetään.',
'Upd_Guide_Phase_Cache' => '{label} – kaikki välimuistit tyhjennetään ja rakennetaan uudelleen.',
'Upd_Guide_Phase_Verify' => '{label} – kuntotarkistukset varmistavat, että uusi versio käynnistyy, tietokanta toimii, kaikki migraatiot suoritettiin ja konfiguraatio on kelvollinen.',
'Upd_Guide_Phase_Done' => '{label} – huoltotila poistetaan ja väliaikaiset tiedostot siivotaan.',
'Upd_Guide_Run_Success' => 'Kun näet viestin {success}, napsauta {reload} ja päivitä selain perusteellisesti ({keys}), jotta uuden hallintapaneelin resurssit latautuvat.',
'Upd_Update_Successful_Short' => 'Päivitys onnistui',
'Upd_Guide_No_Internet' => 'Päivityksen aikana ei tarvita internetyhteyttä – kaikki tulee ladatusta ZIP-tiedostosta. Yhteyden katkeaminen tai selaimen sulkeminen EI riko päivitystä: palvelin muistaa tarkalleen, mihin se jäi.',
'Upd_Guide_Wrong_Title' => '3. Jos jokin menee pieleen',
'Upd_Guide_Wrong_Rollback' => '{label} – jos jokin epäonnistuu tiedostojen muuttamisen alettua (purkuvirhe, migraation epäonnistuminen, epäonnistunut kuntotarkistus, levy täynnä, …), järjestelmä palauttaa automaattisesti aiemmat tiedostot ja tietokannan tarkistetusta varmuuskopiosta, poistaa huoltotilan ja ilmoittaa {message}. Päädyt täsmälleen samaan tilaan kuin aloittaessasi.',
'Upd_Automatic_Rollback' => 'Automaattinen palautus',
'Upd_Failed_Previous_Restored' => 'Päivitys epäonnistui – edellinen versio palautettu',
'Upd_Guide_Wrong_Interrupted' => '{label} (palvelimen uudelleenkäynnistys, aikakatkaisu, suljettu selain, sähkökatko) – kun avaat tämän sivun uudelleen, punainen palkki tarjoaa kaksi turvallista vaihtoehtoa: {resume} (jatkaa täsmälleen siitä vaiheesta, johon se jäi) tai {rollback} (palauttaa edellisen version varmuuskopiosta).',
'Upd_Interrupted_Update' => 'Keskeytynyt päivitys',
'Upd_Guide_Wrong_Unreachable' => '{label} – käytä erillistä työkalua {console} osoitteessa {path}. Se toimii myös silloin, kun sivusto on huoltotilassa tai hallintapaneelin resurssit ovat rikki, ja tarjoaa samat Jatka / Palauta -toiminnot. Huoltonäkymän alareunassa on myös huomaamaton "Ylläpitäjän pääsy" -linkki.',
'Upd_Admin_Unreachable' => 'Hallintapaneeliin ei pääse',
'Upd_Recovery_Console' => 'palautuskonsoli',
'Upd_Guide_Wrong_Locked_Out' => '{label} – päivityksen ollessa käynnissä tällä sivulla näkyy {link}. Tallenna se, jos sinun on päästävä takaisin (esimerkiksi istuntosi vanhennuttua); sen avulla pääset huoltonäkymän ohi kirjautumaan uudelleen.',
'Upd_Locked_Out_Maintenance' => 'Lukittu ulos huoltotilan vuoksi',
'Upd_Bypass_Link' => 'ohituslinkki',
'Upd_Guide_Wrong_Concurrent' => '{label} – hän näkee viestin {message} Vain yksi päivitys voi olla käynnissä kerrallaan.',
'Upd_Another_Admin_Updating' => 'Toinen ylläpitäjä yrittää päivittää samaan aikaan',
'Upd_Guide_Backups_Title' => '4. Varmuuskopiot ja palautus',
'Upd_Guide_Backups_Created' => 'Jokainen päivitys luo varmuuskopion {before} kuin mihinkään kosketaan: kaikki sovellustiedostot, jotka päivitys voi korvata, kopio tiedostosta {env} sekä täydellinen tietokantavedos. Päivitys ei koskaan muuta latauksia eikä kohdetta {storage}, joten ne eivät sisälly varmuuskopioon – pidä niistä omat varmuuskopiosi. Varmuuskopiot säilytetään kohteessa {path}, eikä niihin koskaan pääse verkosta.',
'Upd_Before' => 'ennen',
'Upd_Guide_Backups_Panel' => 'Paneeli {panel} välilehdellä {tab} listaa ne päivämäärän, version ja koon kanssa. Sieltä voit {restore} minkä tahansa täydellisen varmuuskopion (tiedostot + tietokanta – nykyisestä tietokannasta otetaan ensin turvakopio) tai {delete} vanhoja.',
'Upd_Restore_Verb' => 'palauttaa',
'Upd_Delete_Verb' => 'poistaa',
'Upd_Guide_Backups_Retention' => 'Valitse asetuksella {keep}, kuinka monta varmuuskopiota säilytetään; vanhemmat poistetaan automaattisesti jokaisen onnistuneen päivityksen jälkeen. Ainoaa jäljellä olevaa täydellistä varmuuskopiota ei voi koskaan poistaa – sinulla on aina tie takaisin.',
'Upd_Guide_Manual_Title' => '5. Manuaalinen päivitys (varamenetelmä)',
'Upd_Guide_Manual_Text' => 'Jos haluat päivittää käsin tai lataustyökalua ei voi käyttää palvelimellasi, noudata tämän sivun välilehden {tab} vaiheittaisia ohjeita.',
'Upd_Guide_Clear_Cache_First' => 'Jos sivut näyttävät rikkinäisiltä tai tyhjiltä päivityksen jälkeen, tyhjennä ensin selaimesi välimuisti – se on lähes aina syy.',
'Upd_Restore_Backup_Confirm' => 'Palautetaanko tämä varmuuskopio? Nykyiset tiedostot ja nykyinen tietokanta korvataan varmuuskopiolla. Nykyisestä tietokannasta otetaan ensin turvakopio. (v{version} – {date})',
'Woo_Guide_Lead' => 'Miten WooCommerce-kauppa pysyy synkronissa ERP:n kanssa. Alla olevat cron-rivit on muodostettu tälle palvelimelle, joten ne voi kopioida suoraan sille.',
'Woo_Guide_Ways_Note' => 'Toisin kuin Shopify, WooCommerce ei lähetä ERP:lle mitään itsestään – täällä ei ole webhook-vastaanotinta, joten kaikki {in} tuleva saapuu aikataulun mukaan. Vain {out} lähtevä varasto voi olla välitöntä.',
'Woo_In' => 'sisään',
'Woo_Out' => 'ulos',
'Woo_Guide_Both_Ways_Title' => 'Molemmat suunnat tarvitsevat ensin tämän',
'Woo_Api_Keys' => 'API-avaimet',
'Woo_Guide_Api_Keys_Text' => '{path}, käyttöoikeus {perm}. Kopioi consumer key ja secret välilehdelle {settings} yhdessä kaupan URL-osoitteen kanssa – sivustosi osoite ilman loppukauttaviivaa, esim. {example}.',
'Woo_Credentials_Saved' => 'tunnukset tallennettu',
'Woo_Not_Configured_Yet' => 'ei vielä määritetty',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress-sovellussalasana (valinnainen)',
'Woo_Guide_Wp_App_Password_Text' => 'Käytetään vain tuotekuviin. WooCommerce API siirtää tuotteet, varastot, kategoriat, brändit, asiakkaat ja tilaukset; WordPress API hakee mediakirjastosta ja lataa kuvan, jota siellä ei vielä ole.',
'Woo_Guide_Wp_App_Password_Note' => 'Käytä WordPress-käyttäjää, joka voi hallita mediaa, ja luo salasana kohdassa {path}. Jätä molemmat kentät tyhjiksi, niin kaikki synkronoituu silti – vain kuvien liittäminen ohitetaan.',
'Woo_Guide_Pick_Way_Title' => 'Valitse sitten, miten synkronointi pidetään ajan tasalla',
'Woo_Right_Away' => 'Heti',
'Woo_Stock_Live' => 'varasto reaaliajassa',
'Woo_Stock_Not_Live' => 'varasto ei reaaliajassa',
'Woo_Guide_Realtime_Lead' => 'Vain yksi suunta: ERP:stä lähtevät varastot ja tuotteet. WooCommercessa tehdyt tilaukset ja tuotemuutokset saapuvat edelleen aikataulun mukaan – katso toinen välilehti.',
'Woo_Push_Stock_On_Change' => 'Lähetä varasto heti sen muuttuessa',
'Woo_Setting_People_Miss' => 'Tämä asetus jää usein huomaamatta',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS-myynti {not} välity WooCommerceen itsestään. Jos asetus on pois päältä, kauppa saa tiedon vasta seuraavassa varastosynkronoinnissa – oletuksena tunnin kuluttua – ja sillä välin se voi myydä yksikön, jonka olet jo myynyt kassalla.',
'Woo_Does_Not' => 'ei',
'Woo_Guide_Tick_Instant' => 'Valitse {option} välilehdellä {settings}. Siinä koko määritys – ei työprosessia, ei cronia. Jokainen myynti, palautus, oikaisu, siirto ja vastaanotettu osto lähettää sitten päivityksen vain kyseisistä tuotteista heti myynnin tallentamisen jälkeen, ja kahdenkymmenen rivin myynti vaatii yhden päivityksen, ei kahtakymmentä. Kassa ei koskaan odota sitä.',
'Woo_Currently' => 'Tällä hetkellä:',
'Woo_Instant_On_Text' => 'päällä – varasto lähetetään muuttuessa',
'Woo_Instant_Off_Text' => 'pois – varasto vain aikataulun mukaan',
'Woo_Guide_Instant_Note' => 'Vain WooCommerceen jo linkitetyt tuotteet lähetetään – tuotteella, jota ei ole koskaan synkronoitu, ei ole kaupassa mitään korjattavaa. Muunnelmatuotteet kulkevat päätuotteensa kautta, ja yhdistelmätuote lähetetään uudelleen, kun jokin sen komponenteista liikkuu. Joukkotoiminnot (tuotteen poistaminen, varaston nollaus) kirjoittavat varaston laukaisematta tapahtumaa, mikä on yksi syy pitää myös tunnittainen varastosynkronointi.',
'Woo_Push_Products_On_Save' => 'Lähetä tuotteet heti tallennettaessa',
'Woo_Guide_Tick_Auto_Products' => 'Valitse {option} välilehdellä {settings}, niin Stockyssa luotu, muokattu tai monistettu tuote lähetetään WooCommerceen heti tallennuksen jälkeen – tiedot, hinta, muunnelmat ja kuvat, sitten sen varasto. Uusi tuote luodaan kauppaan heti sen sijaan, että odotettaisiin öistä tuotesynkronointia.',
'Woo_On' => 'päällä',
'Woo_Off' => 'pois',
'Woo_Guide_Bulk_Imports_Note' => 'Joukkotuonteja ei lähetetä yksitellen – suorita tuotesynkronointi tuonnin jälkeen. Synkronoi ensin kategoriat ja brändit, jotta lähetetty tuote päätyy oikeaan kategoriaan.',
'Woo_Nothing_Else_To_Install' => 'Ei muuta asennettavaa',
'Woo_Guide_Same_Process' => 'Ei jonotyöprosessia, ei cron-merkintää. Päivitys suoritetaan samassa prosessissa, joka käsitteli myynnin, vasta sen {after}, kun vastaus on palautettu, joten kassa ei koskaan odota WooCommercea. Päivitykset eivät koskaan mene päällekkäin: yhden ollessa käynnissä tehdyt muutokset odottavat sitä ja lähtevät heti sen jälkeen.',
'Woo_After' => 'jälkeen',
'Woo_Guide_Shop_Stops_Answering' => 'Kauppa, joka lakkaa vastaamasta, hylätään kahdeksan sekunnin jälkeen, ja päivitykset keskeytetään viideksi minuutiksi, jotta jokainen myynti ei odota sitä uudelleen; sillä välin tulleet muutokset lähtevät ensimmäisen tauon jälkeisen päivityksen mukana, ja tunnittainen varastosynkronointi korjaa tilanteen joka tapauksessa. Jokainen tauko kirjataan Lokit-välilehdelle.',
'Woo_Guide_Artisan_Exception' => 'Yksi poikkeus: artisan-komennolla tehdyllä varastomuutoksella ei ole vastausta, jonka jälkeen se voitaisiin suorittaa, joten se asetetaan sen sijaan jonoon {queue}. Jotta myös ne lähtevät viipymättä, tyhjennä kyseinen jono:',
'Woo_Cron_Line_Copied' => 'Cron-rivi kopioitu',
'Woo_Command_Copied' => 'Komento kopioitu',
'Woo_Guide_Not_Woo_Queue' => 'Tarkoituksella ei jono {queue}: se kuljettaa tuntien mittaisia luetteloeriä, eikä niiden taakse jonotettu välitön päivitys olisi välitön.',
'Woo_On_A_Schedule' => 'Aikataulun mukaan',
'Woo_Guide_Scheduled_Lead' => 'Kaikki tarkistetaan uudelleen säännöllisesti molempiin suuntiin. Näin tilaukset saapuvat ERP:hen, näin luettelo julkaistaan ja näin korjataan kaikki, mikä nopealta reitiltä jäi huomaamatta. Jokaisella työllä on oma cron-merkintänsä, joten suoritat vain haluamasi.',
'Woo_Guide_Sync_Drains_Queue' => '{command} tyhjentää oman jononsa suorituksen aikana, joten nämä rivit eivät tarvitse erillistä työprosessia. Windowsissa käytä Tehtävien ajoitusta ohjelmalla {program} ja samoilla argumenteilla, käynnistettynä kansiossa {path}.',
'Woo_Or_No_Cron' => 'Tai ei cronia lainkaan',
'Woo_Guide_No_Cron_Text' => 'Jokainen tämän sivun välilehti synkronoi pyynnöstä, ja manuaalinen synkronointi tyhjentää omat eränsä sivun ollessa auki – joten pieni kauppa voi toimia ilman yhtään cron-merkintää. Menetät kaiken, mitä tapahtuu kenenkään katsomatta: tilaukset saapuvat vasta, kun joku painaa painiketta.',
'Woo_Commands_Worth_Knowing' => 'Hyödyllisiä komentoja',
'Woo_Worth_Knowing' => 'Hyvä tietää',
'Woo_Guide_Changing_Url_Clears' => 'Kaupan URL-osoitteen tai API-avainten muuttaminen tyhjentää kaikki yhdistämiset – tuotteet, kategoriat, brändit ja asiakkaat synkronoidaan kaikki uudelleen uuteen kauppaan.',
'Woo_Guide_Keep_Skus' => 'Pidä SKU:t yhdenmukaisina Stockyn ja WooCommercen välillä: se estää kaksoiskappaleet ja tekee uudelleenlinkityksestä turvallista.',
'Woo_Guide_Stock_Total' => 'Wooon julkaistu varasto on {total}, ei yhden varaston luku.',
'Woo_Total_Across_Warehouses' => 'kaikkien varastojen yhteissaldo',
'Woo_Guide_Full_Reference' => 'Täydellinen ohje – jokainen laajuus, jonon toiminta ja vianmäärityslista – löytyy tiedostosta {file}.',
'Woo_Way_Covers' => 'Kattaa',
'Woo_Way_Covers_Realtime' => 'Vain ERP:stä lähtevä varasto – POS-myynti, palautus, oikaisu, vastaanotettu osto',
'Woo_Way_Covers_Scheduled' => 'Kaikki molempiin suuntiin: tilaukset ja tuotemuutokset sisään, luettelo ja varasto ulos',
'Woo_Way_Speed' => 'Nopeus',
'Woo_Way_Seconds' => 'Sekunteja',
'Woo_Way_Speed_Scheduled' => 'Mitä tahansa asetat cron-merkintään (varasto tunneittain, tilaukset 15 min välein)',
'Woo_Way_Needs' => 'Vaatii',
'Woo_Way_Needs_Realtime' => 'Ei mitään – vain asetuksen',
'Woo_Way_Needs_Scheduled' => 'Cron-merkinnän työtä kohden – tai ei mitään, jos synkronoit käsin',
'Woo_Way_Switched_On_At' => 'Kytketään päälle',
'Woo_Way_Cron_Entries_Below' => 'Alla olevat cron-merkinnät',
'Woo_Cron_Orders' => 'Tilaukset 15 minuutin välein – vain edellisen ajon jälkeen muuttuneet.',
'Woo_Cron_Products_Pull' => 'Kaupan tuotemuutokset joka yö klo 03:00.',
'Woo_Cron_Customers' => 'Asiakkaat joka yö klo 03:30.',
