'Shopify_Auto_On_Note' => 'Ohjataan cron-merkinnällä, joka suorittaa {cmd} – ilman sitä mikään tässä ei suoritu itsestään. Manuaalinen synkronointi lasketaan ajoksi: se siirtää seuraavaa ajoa vaiheen aikavälin verran.',
'Shopify_Stock_Lag_Title' => 'Varasto välittyy Shopifyhin vain, kun Varaston lähetys -vaihe suoritetaan',
'Shopify_Stock_Lag_Desc' => 'Myymälässä tehty myynti pysyy kaupalle näkymättömänä siihen asti – jopa {n} minuuttia, joten viimeinen yksikkö voidaan yhä myydä verkossa kahdesti. Kytke {setting} päälle, niin jokainen myynti, palautus ja oikaisu lähetetään sen sijaan sekunneissa.',
'Shopify_Turn_It_On' => 'Kytke päälle',
