'Shopify_Hook_Msg_Token' => 'Napsauta alla ”Rekisteröi webhookit” ja liitä sovelluksen API secret key kaupan asetuksiin allekirjoitussalaisuudeksi.',
'Shopify_Hook_Note_Register' => 'Rekisteröinti luo tilaukset Shopifyhin ja osoittaa ne automaattisesti tähän osoitteeseen. Älä lisää sitä käsin kohtaan Shopify → Settings → Notifications → Webhooks: ne allekirjoitetaan eri salaisuudella ja jokainen toimitus hylättäisiin.',
