'Shopify_Hook_Retries' => 'Shopify yrittää uudelleen, kunnes se saa 2xx-vastauksen, ja jokainen toimitus kirjataan kerran – toistuva tapahtuma ei tee mitään eikä luo kaksoistilausta.',
'Shopify_No_Signing_Secret' => 'Allekirjoitussalaisuutta ei ole tallennettu',
'Shopify_No_Signing_Secret_Desc' => 'Tilaukset voidaan luoda ilman sitä, mutta jokainen toimitus hylätään, kunnes sovelluksen API secret key on tallennettu tähän kauppaan (Dev Dashboard -sovelluksen client secret kattaa jo tämän).',
