'Shopify_Could_Not_Load_Store' => 'Tätä kauppaa ei voitu ladata',
'Shopify_G_Lead_Store' => 'Mitä tämä kauppa tarvitsee pysyäkseen ajan tasalla. Kaikki tässä koskee juuri tätä kauppaa – polut ja ID:t ovat todellisia, joten komennot voi kopioida suoraan palvelimelle.',
'Shopify_G_Lead_Generic' => 'Miten Shopify-kauppa pysyy synkronissa ERP:n kanssa. Valitse kauppa yltä nähdäksesi sen oman tilan tai lue tämä sellaisenaan – cron-rivi ja webhook-URL ovat samat, minkä tahansa kaupan yhdistätkin.',
'Shopify_G_Ways_Note' => 'Useimmat kaupat käyttävät molempia: ensimmäinen pitää kaupan ajan tasalla minuutti minuutilta, toinen nappaa sen, mitä ensimmäiseltä jäi – webhookin, joka ei koskaan saapunut, suoraan Shopifyn hallinnassa tehdyn muokkauksen, yön, jolloin sivusto oli alhaalla.',
'Shopify_G_Both_Need' => 'Molemmat suunnat tarvitsevat ensin tämän',
'Shopify_G_Credentials' => 'Shopify-tunnukset',
'Shopify_G_Cred_Intro' => 'Tammikuusta 2026 alkaen Shopify ei enää luo mukautettuja sovelluksia hallinnan sisällä, joten yhteyksiä on kahdenlaisia:',
'Shopify_G_Cred_DevDash' => '{app} (mikä tahansa nyt yhdistetty kauppa) – {path}. Myönnä Admin API -oikeudet sille, mitä tämä kauppa synkronoi, asenna sovellus kauppaan ja kopioi sitten {clientId} ja {clientSecret} sovelluksen Settings-sivulta kohtaan {where}. ERP vaihtaa ne itse käyttötunnukseen ja uusii sen ennen kuin se vanhenee 24 tunnin välein. Client secret allekirjoittaa myös webhookit, joten muuta ei tarvita. Sovelluksen ja kaupan on oltava samassa Shopify-organisaatiossa.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard -sovellus',
'Shopify_G_Cred_Legacy' => '{app} (luotu hallinnassa ennen vuotta 2026) – toimii edelleen muuttumattomana tunnuksellaan {token} ({prefix}) ja käyttää kohdetta {secret} webhookin allekirjoitussalaisuutena. Se ei ole sama arvo kuin tunnus, ja niiden sekoittaminen keskenään on tavallinen syy webhookien hylkäämiseen.',
'Shopify_G_Legacy_App' => 'Vanha mukautettu sovellus',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'tallennettu',
'Shopify_G_Missing_Refused' => 'puuttuu – toimitukset hylätään',
'Shopify_G_Where_Data_Desc' => '{path} ERP-varasto, jonka varastoa tämä kauppa myy, ja Shopify-sijainti, johon varasto kirjoitetaan. Varaston synkronointi ja tilausten tuonti eivät suostu toimimaan ilman niitä.',
'Shopify_G_Currently' => 'Tällä hetkellä: varasto {warehouse}, sijainti {location}',
'Shopify_G_Not_Set_Lower' => 'ei asetettu',
'Shopify_G_Ready' => 'valmis',
'Shopify_G_Incomplete' => 'keskeneräinen',
'Shopify_G_Manual_Syncs' => 'Käsin aloitettavat synkronoinnit',
'Shopify_G_Manual_Desc' => 'Kohdasta {centre} aloitettu synkronointi vastaa heti ja suoritetaan taustalla lyhyinä osina, joista kukin jatkaa siitä, mihin edellinen jäi. Suuri luettelo ei koskaan katkea kesken webhotellin pitkiä verkkopyyntöjä katkaisevien asetusten vuoksi (LiteSpeed, nginx, kuormantasaaja), eikä sivun sulkeminen pysäytä sitä. Sen työprosessi on yksi cron-rivi lisää:',
'Shopify_G_Cron_Copied' => 'Cron-rivi kopioitu',
'Shopify_G_Manual_Note' => 'Ilman sitä synkronointi valmistuu silti, mutta vain niin kauan kuin Sync Centre -sivu pysyy auki: kun mikään työprosessi ei ota ajoa vastaan muutamassa sekunnissa, sivu jatkaa sitä itse lyhyt pyyntö kerrallaan. Windowsissa käytä Tehtävien ajoitusta minuutin välein: ohjelma {program}, argumentit {args}, käynnistettynä kansiossa {dir}.',
'Shopify_G_Then_Pick' => 'Valitse sitten, miten synkronointi pidetään ajan tasalla',
'Shopify_G_Right_Away' => 'Heti',
'Shopify_G_Stock_Live' => 'varasto reaaliajassa',
'Shopify_G_Stock_Not_Live' => 'varasto ei reaaliajassa',
'Shopify_G_Realtime_Lead' => 'Jokainen muutos lähetetään sen tapahtuessa, sekunneissa. Kaksi puoliskoa, ja ne ovat erillisiä kytkimiä: {webhooks} tuovat kaupan omat tapahtumat sisään ja {push} lähettää varaston ulos.',
'Shopify_G_Webhooks_Lower' => 'webhookit',
'Shopify_G_Instant_Push_Lower' => 'välitön varastopäivitys',
'Shopify_G_Webhooks_In' => 'Webhookit – kauppa → ERP',
'Shopify_G_Webhooks_Desc' => 'Tilaukset, tilausten tilamuutokset sekä Shopifyssa tehdyt tuote-, asiakas- ja varastomuutokset. Avaa kauppa ja paina {button} sen välilehdellä {tab} – turvallista painaa kahdesti. Shopify lähettää osoitteeseen:',
'Shopify_G_Webhooks_Tab' => 'Webhookit-välilehti',
'Shopify_G_Webhooks_Note' => 'Osoitteen on oltava tavoitettavissa internetistä HTTPS:n kautta – Shopify ei toimita osoitteeseen {localhost} tai {test}-verkkotunnukseen. Jokainen toimitus kirjataan kerran, joten Shopifyn uudelleenyritykset eivät voi luoda kaksoistilausta, ja epäonnistuneen voi toistaa. Toimitukset hylätään, kunnes vaiheen 1 allekirjoitussalaisuus on tallennettu.',
'Shopify_G_Instant_Out' => 'Välitön varastopäivitys – ERP → kauppa',
'Shopify_G_Setting_Missed' => 'Tämä asetus jää usein huomaamatta',
'Shopify_G_Pos_Not_Auto' => 'POS-myynti {not} välity Shopifyhin itsestään. Jos asetus on pois päältä, kauppa saa tiedon vasta seuraavassa Varaston lähetys -vaiheessa – ja sillä välin se voi myydä yksikön, jonka olet jo myynyt kassalla.',
'Shopify_G_Not' => 'ei',
'Shopify_G_Tick_Push' => 'Valitse {setting} kohdassa {where}. Siinä koko määritys – ei työprosessia, ei cronia. Jokainen myynti, palautus ja oikaisu lähettää sitten päivityksen vain kyseisistä tuotteista heti myynnin tallentamisen jälkeen, ja kahdenkymmenen rivin myynti vaatii yhden päivityksen, ei kahtakymmentä. Kassa ei koskaan odota sitä.',
'Shopify_G_This_Store' => 'Tämä kauppa:',
'Shopify_G_Push_On' => 'päällä – varasto lähetetään muuttuessa',
'Shopify_G_Push_Off' => 'pois – varasto vain aikataulun mukaan',
'Shopify_G_Push_Note' => 'Vain tuotteet, joilla on jo Shopify-yhdistäminen, ja vain tämän kaupan varaston liikkeet lähetetään. Joukkotoiminnot – tuotteen poistaminen, varaston nollaus – kirjoittavat varaston laukaisematta tapahtumaa, mikä on yksi syy pitää myös ajastettu varastovaihe.',
'Shopify_G_Nothing_Install' => 'Ei muuta asennettavaa',
'Shopify_G_No_Worker_Note' => 'Kumpikaan puolisko ei tarvitse jonotyöprosessia eikä cron-merkintää. Saapuva webhook käsitellään Shopifyn tekemässä pyynnössä; lähtevä varastopäivitys suoritetaan samassa prosessissa, joka käsitteli myynnin, vasta sen {after}, kun vastaus on palautettu – joten kassa ei koskaan odota Shopifya, ja kauppa, joka lakkaa vastaamasta, hylätään kymmenen sekunnin jälkeen ja jätetään seuraavalle ajastetulle varastolähetykselle.',
'Shopify_G_After' => 'jälkeen',
'Shopify_G_Artisan_Note' => 'Yksi poikkeus: artisan-komennolla tehdyllä varastomuutoksella ei ole vastausta, jonka jälkeen se voitaisiin suorittaa, joten se asetetaan sen sijaan jonoon {queue}. Jos haluat myös niiden lähtevän viipymättä, tyhjennä kyseinen jono:',
'Shopify_G_On_Schedule' => 'Aikataulun mukaan',
'Shopify_G_On_Lower' => 'päällä',
'Shopify_G_Off_Lower' => 'pois',
'Shopify_G_Scheduled_Lead' => 'Kaikki tarkistetaan uudelleen säännöllisesti molempiin suuntiin. Hitaampaa kuin reaaliaikainen, mutta se lähettää varaston ulos kaupoissa, jotka eivät käytä välitöntä päivitystä, nappaa väliin jääneen webhookin ja on ainoa tapa siirtää koko luettelo.',
'Shopify_G_Cron_Entry' => 'Cron-merkintä',
'Shopify_G_Cron_Entry_Desc' => 'Mitään ajastettua ei suoriteta ilman sitä. Yksi rivi, vain tälle moduulille – lisää se muiden ajastamiesi rivien viereen:',
'Shopify_G_Cron_Note' => 'Viisi minuuttia on tihein tarkkuus, jota suunnitelma voi käyttää, koska viisi minuuttia on lyhyin vaiheen aikaväli. Harvempi merkintä muuttuu yksinkertaisesti alarajaksi – merkinnällä {example} 5 minuutiksi asetettu vaihe suoritetaan 15 minuutin välein. Windowsissa käytä Tehtävien ajoitusta: ohjelma {program}, argumentit {args}, käynnistettynä kansiossa {dir}.',
'Shopify_G_Switch_On_Plan' => 'Kytke se päälle ja valitse suunnitelma',
'Shopify_G_Plan_Desc' => '{where} Kytkin ratkaisee, saako cron toimia lainkaan; suunnitelma ratkaisee, mitä se tekee. {step} on yksi entiteetti yhteen suuntaan omalla aikavälillään – {first}, {second}. Oletusaikaväliä käytetään jokaisessa vaiheessa, jonka oma kenttä on tyhjä.',
'Shopify_G_Step_Lower' => 'vaihe',
'Shopify_G_Plan_Note' => 'Jätä suunnitelma tyhjäksi, niin kauppa hakee tilaukset ja lähettää varaston oletusaikavälein, mitä useimmat kaupat haluavat. Tilaukset ovat vain haettavia: Shopify on paikka, jossa asiakas tekee tilauksen.',
'Shopify_G_Schedule_On' => 'ajastus päällä',
'Shopify_G_Schedule_Off' => 'ajastus pois – vain manuaalinen',
'Shopify_G_When_Step_Runs' => 'Milloin vaihe todella suoritetaan',
'Shopify_G_When_Note' => 'Vaihe erääntyy, kun sama vaihe viimeksi {started} aikaväliään kauemmin sitten, ajohistorian perusteella. Käsin aloitettu synkronointi siis lykkää seuraavaa automaattista, ja jatkuvasti epäonnistuvaa vaihetta yritetään uudelleen aikavälinsä mukaan eikä joka kierroksella. Kaupan Yleiskatsaus näyttää kunkin vaiheen viimeisimmän ajon, seuraavan eräajan ja syyn, jos se on estetty. Suorita ensimmäinen luettelolähetys käsin – ensin {dryRun} – ennen kuin asetat sen aikatauluun.',
'Shopify_G_Started_Lower' => 'alkoi',
'Shopify_G_Where_Setting' => 'Missä kukin asetus on',
'Shopify_G_Where_Setting_Note' => 'Kaikki nämä ovat olemassa olevassa kaupassa: {path}, sitten kynäkuvake (tai {edit} kaupan omalla sivulla).',
'Shopify_G_Product_Images' => 'Tuotekuvat',
'Shopify_G_Img_1' => 'Kuvat lähtevät tuotteen mukana {push} – ensin pääkuva, sitten galleria ja sitten yksi kutakin omaa kuvaa käyttävää muunnelmaa kohden, enintään viisikymmentä.',
'Shopify_G_Products_Push' => 'tuotteiden lähetyksessä',
'Shopify_G_Img_2' => 'Muunnelman kuva ladataan tuotteen mukana ja sitten {assigned}, mikä vastaa Shopifyn mallia: muunnelma osoittaa yhteen tuotteen kuvista. Pääkuvaa uudelleenkäyttävä muunnelma ei lataa sitä kahdesti.',
'Shopify_G_Assigned' => 'määritetään kyseiselle muunnelmalle',
'Shopify_G_Img_3' => 'Tiedostona tallennettu kuva {uploaded} Shopifyhin, ei linkitetä, joten se toimii, vaikka tähän asennukseen ei olisi yhteyttä internetistä. Liitettynä linkkinä lisätty kuva annetaan Shopifylle kyseisenä URL-osoitteena, jonka on oltava julkisesti tavoitettavissa.',
'Shopify_G_Uploaded' => 'ladataan',
'Shopify_G_Img_4' => 'Ne lähetetään uudelleen vain, kun ne todella muuttuvat – lähetys, joka muuttaa vain hintaa, jättää kaupan kuvat ennalleen, koska niiden lähettäminen korvaa koko kuvasarjan.',
'Shopify_G_Img_5' => 'Kuvan poistaminen ERP:stä {not} poista sitä Shopifysta. Poista se myös sieltä, muuten kauppa näyttää sitä edelleen.',
'Shopify_G_Commands' => 'Hyödyllisiä komentoja',
'Shopify_G_Command_Copied' => 'Komento kopioitu',
'Shopify_G_Foot' => 'Jokainen synkronointi kirjoittaa kohteeseen {logs}, ja kunkin kaupan Yleiskatsaus näyttää, milloin kukin vaihe viimeksi suoritettiin, milloin se seuraavaksi erääntyy ja mikä sitä estää, jos jokin estää. Sieltä kannattaa katsoa ensin, kun synkronointi ei tehnyt odottamaasi.',
'Shopify_G_Covers' => 'Kattaa',
'Shopify_G_Covers_Rt' => 'Shopifyssa tehdyt tilaukset ja muokkaukset; ERP:stä lähtevä varasto (POS-myynti, palautus, oikaisu)',
'Shopify_G_Covers_Sch' => 'Kaikki molempiin suuntiin – mukaan lukien luettelolähetykset ja kaikki, mikä nopealta reitiltä jäi huomaamatta',
'Shopify_G_Speed' => 'Nopeus',
'Shopify_G_Speed_Rt' => 'Sekunteja',
