'Shopify_G_Needs_Sch' => 'Cron-merkintä, joka suorittaa {cmd}',
'Shopify_G_Switched_On_At' => 'Kytketään päälle',
'Shopify_G_On_Sch' => '{path} sekä suunnitelma',
'Shopify_G_Scope_Orders' => '{scope} ({extra} yli 60 päivää vanhoille tilauksille)',
'Shopify_G_Admin_Scopes' => 'Admin API -oikeudet',
