'StoreAdm_Stock_Required_Available' => '{name}: Vaaditaan {need} – Saatavilla {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPalia, Paystackia, Flutterwavea, Razorpayta, bKashia ja SSLCommerzia käytetään vain VERKKOKAUPAN kassalla.',
