'Cr_Guide_T_Booking' => 'Tilausten varaaminen',
'Cr_Guide_B_Booking' => 'Lähetä kuriirille täyttää lomakkeen myynnin tiedoista: vastaanottaja, osoite, vielä avoinna oleva summa COD-summana sekä tuotteiden paino. Kuriireille, joilla on omat kaupunkiluettelonsa, näytetään valitsin, ja valintasi muistetaan kyseiselle kaupungille. Aggregaattorit, DHL, FedEx, UPS ja Lalamove tarjoavat Vertaa hintoja -toiminnon: valitse hinta, ja Varaa ostaa sen. Useita myyntejä voi varata kerralla myyntiluettelosta.',
'Cr_Guide_T_Cod' => 'Jälkivaatimus',
'Cr_Guide_B_Cod' => 'COD-paketin tila etenee: Ei peritty → Kuriiri perinyt (toimitettaessa) → Tilitetty sinulle. Tilityksistä ilmoittavat kuriirit siirtävät viimeisen vaiheen itse; muille käytä Päivitä COD -toimintoa. Kun kuriiriasetuksissa on valittu tili, tilitys kirjataan myynnille maksuksi. Kuriirimaksut voidaan tallentaa kuluksi, kun paketti on valmis.',
'Cr_Guide_T_Returns' => 'Palautetut paketit',
'Cr_Guide_B_Returns' => 'Oletuksena palautettu paketti odottaa Kuriirilähetykset-sivulla kohdassa Tarkistettavat palautukset. Palauta varastoon luo myynnin palautuksen koko tilaukselle ja palauttaa tuotteet varastoon; Ohita ei palauta mitään, ja se on tarkoitettu vaurioituneille tai kadonneille paketeille. Kuriiriasetuksissa voidaan sen sijaan valita automaattinen palautus varastoon.',
'Cr_Guide_T_Customers' => 'Asiakasviestit ja seurantasivu',
'Cr_Guide_B_Customers' => 'Kuriiriasetusten asiakasilmoitukset lähettävät SMS-, sähköposti- tai WhatsApp-viestin valitsemissasi tiloissa, kunkin kerran pakettia kohden, omalla tekstilläsi. Verkkokauppasi seurantasivulla asiakkaat voivat seurata pakettia seurantanumerolla tai tilausnumerolla ja puhelinnumerolla. Asiakkaat, jotka palauttavat paketteja usein, saavat palautusriskimerkin varattaessa.',
'Cr_Guide_T_Labels' => 'Osoitetarrat',
'Cr_Guide_B_Labels' => 'Tulosta osoitetarra antaa kuriirin oman tarran, kun kuriiri sellaisen tarjoaa (PDF, linkki tai kuva), muuten Stockyn tarran, jossa on seurantaviivakoodi ja perittävä summa. Salli ponnahdusikkunat tälle sivustolle tulostamista varten. DHL, FedEx ja UPS antavat tarransa vain kerran varauksen yhteydessä, ja Stocky säilyttää sen uudelleentulostusta varten.',
'Cr_Guide_T_Faq' => 'Vianmääritys',
'Cr_Guide_Q_Test' => 'Yhteystesti epäonnistuu',
'Cr_Guide_A_Test' => 'Testiavaimet kuuluvat Testitilaan ja tuotantoavaimet Tuotanto-tilaan; ne ovat eri avaimet. Avaa Kuriirilokit ja lue kuriirin vastauksesta tarkka syy.',
'Cr_Guide_Q_City' => 'Kuriiri hylkää kaupungin tai osoitteen',
'Cr_Guide_A_City' => 'Valitse kaupunki varauslomakkeen kuriirin kaupunkiluettelosta; kuriirit hyväksyvät vain omat nimensä. Postiosoitteilla toimivat kuriirit tarvitsevat lisäksi osavaltion, postinumeron ja kaksikirjaimisen maakoodin.',
'Cr_Guide_Q_Webhook' => 'Tilat eivät muutu itsestään',
'Cr_Guide_A_Webhook' => 'Päivityksiä lähettävien kuriirien kohdalla tarkista, että webhook-URL on rekisteröity kuriirille: Kuriirilokit näyttää jokaisen vastaanotetun päivityksen tai syyn sen hylkäämiseen (esimerkiksi väärä salaisuus). Muut kuriirit tarkistetaan kuriiriasetusten aikataulun mukaan, ja Tarkista tila nyt kysyy heti.',
'Cr_Guide_Q_Stuck' => 'Lähetyksessä näkyy tilan tarkistuksen virhe',
'Cr_Guide_A_Stuck' => 'Kuriiri hylkäsi viimeisimmät tarkistukset; syy näkyy lähetyksessä ja Kuriirilokeissa. Toistuvien epäonnistumisten jälkeen lähetystä ei enää tarkisteta automaattisesti: korjaa syy ja käytä sitten Tarkista tila nyt -toimintoa.',
'Cr_Guide_Q_Label' => 'Mitään ei avaudu osoitetarraa tulostettaessa',
'Cr_Guide_A_Label' => 'Selaimesi esti ponnahdusikkunan. Salli ponnahdusikkunat tälle sivustolle ja yritä uudelleen.',
'Cr_Guide_Q_Cod' => 'COD-tilitystä ei kirjattu myyntiin',
'Cr_Guide_A_Cod' => 'Kuriiriasetuksissa jälkivaatimuksen kytkimen on oltava päällä ja tilin valittuna. Ilman tiliä tilitykset vain merkitään tilitetyiksi.',
