'Tfa_Codes_Save' => 'Tallenna nämä palautuskoodit turvalliseen paikkaan. Kullakin voit kirjautua kerran, jos kadotat puhelimesi. Niitä ei näytetä uudelleen.',
'Tfa_Reset' => 'Nollaa kaksivaiheinen tunnistautuminen',
'Tfa_Reset_Title' => 'Nollataanko kaksivaiheinen tunnistautuminen?',
'Tfa_Reset_Help' => 'Käyttäjä :name kirjautuu pelkällä salasanallaan ja voi sen jälkeen määrittää todennussovelluksensa uudelleen. Tee tämä vain, kun olet varmistanut pyytäjän henkilöllisyyden.',
'Tfa_Guide_Lead' => 'Kaksivaiheinen tunnistautuminen (2FA) lisää kirjautumiseen toisen vaiheen: salasanan jälkeen henkilöstö syöttää 6-numeroisen koodin puhelimensa todennussovelluksesta. Varastettu tai arvattu salasana ei enää riitä sisäänpääsyyn.',
