'Tfa_Guide_State_Users' => 'Käyttäjät, joilla 2FA on käytössä',
'Tfa_Guide_Staff_Title' => 'Jokaiselle henkilöstön jäsenelle',
'Tfa_Guide_App_Title' => 'Asenna todennussovellus',
'Tfa_Guide_App_Text' => 'Mikä tahansa vakiomuotoisia 6-numeroisia koodeja (TOTP) tukeva sovellus käy. Ne ovat maksuttomia ja toimivat ilman verkkoyhteyttä:',
'Tfa_Guide_Enable_Title' => 'Ota käyttöön profiilista',
'Tfa_Guide_Enable_1' => 'Avaa Profiili (avatar-valikko oikeassa yläkulmassa) ja etsi kortti ”Kaksivaiheinen tunnistautuminen”.',
'Tfa_Guide_Enable_2' => 'Napsauta ”Ota käyttöön” ja vahvista nykyisellä salasanalla.',
'Tfa_Guide_Enable_3' => 'Skannaa QR-koodi sovelluksella tai kirjoita sen alla näkyvä avain.',
'Tfa_Guide_Enable_4' => 'Viimeistele syöttämällä sovelluksen näyttämä 6-numeroinen koodi.',
'Tfa_Guide_Open_Profile' => 'Avaa profiilini',
'Tfa_Guide_Codes_Title' => 'Tallenna palautuskoodit',
'Tfa_Guide_Codes_Text' => 'Heti käyttöönoton jälkeen näytetään kerran 8 palautuskoodia. Kukin korvaa puhelimen koodin yhden kerran — jos puhelin katoaa, rikkoutuu tai palautetaan tehdasasetuksiin. Lataa tai kopioi ne ja säilytä turvallisessa paikassa erillään puhelimesta.',
'Tfa_Guide_Codes_Note' => 'Koodit vähissä? Profiilin ”Uudet palautuskoodit” korvaa koko sarjan; vanhat lakkaavat toimimasta.',
'Tfa_Guide_Signin_Title' => 'Kirjautuminen',
'Tfa_Guide_Signin_Text' => 'Sähköpostiosoitteen ja salasanan jälkeen kirjautumissivu kysyy sovelluksen nykyistä koodia. Koodit vaihtuvat 30 sekunnin välein, ja kukin toimii vain kerran.',
'Tfa_Guide_Signin_Trust' => 'Valinta ”Älä kysy uudelleen tällä laitteella” ohittaa koodin kyseisessä selaimessa :days päivän ajan.',
'Tfa_Guide_Signin_Recovery' => 'Eikö puhelin ole käsillä? Napsauta ”Käytä palautuskoodia” ja kirjoita yksi tallennetuista koodeista.',
'Tfa_Guide_Admin_Title' => 'Järjestelmänvalvojille',
'Tfa_Guide_Require_Title' => 'Tee siitä pakollinen',
'Tfa_Guide_Require_Text' => 'Ota tällä kortilla käyttöön ”Vaadi kaksivaiheinen tunnistautuminen” ja valitse roolit, joiden on käytettävä sitä — tai jätä luettelo tyhjäksi, jolloin se koskee kaikkia käyttäjiä. Tallenna napsauttamalla Lähetä.',
'Tfa_Guide_Require_Next' => 'Ketään ei kirjata ulos. Käyttäjät, joilla ei vielä ole 2FA:ta, ohjataan käyttöönottoon kirjautumissivulla seuraavalla kirjautumisellaan ennen sisäänpääsyä, ja he näkevät palautuskoodinsa siellä.',
'Tfa_Guide_Require_Note' => 'Käyttäjät, joilta sitä vaaditaan, eivät voi poistaa sitä käytöstä profiilistaan.',
'Tfa_Guide_Trust_Title' => 'Luotetut laitteet',
'Tfa_Guide_Trust_Text' => '”Muista luotetut laitteet” määrittää, kuinka kauan selain voi ohittaa koodin onnistuneen kirjautumisen jälkeen. Valitse ”Kysy koodia aina” yhteiskäyttöisille tai julkisille tietokoneille, kuten myymälän POS-kassalle.',
'Tfa_Guide_Trust_Note' => 'Määrän pienentäminen lyhentää myös jo luotettujen laitteiden aikaa; 2FA:n poistaminen käytöstä tai nollaaminen unohtaa ne kaikki.',
'Tfa_Guide_Lost_Title' => 'Kadonnut puhelin eikä palautuskoodeja',
'Tfa_Guide_Lost_Text' => 'Käyttäjät-sivulla 2FA-sarakkeessa näkyy ”Käytössä” käyttäjillä, joilla 2FA on käytössä. Toiminnot-sarakkeen kilpipainike nollaa sen: käyttäjä kirjautuu pelkällä salasanalla ja määrittää sovelluksen uudelleen (tai häntä pyydetään tekemään niin, jos se on pakollinen).',
'Tfa_Guide_Lost_Warn' => 'Varmista pyytäjän henkilöllisyys ennen nollaamista — nollaus poistaa 2FA:n tuoman suojan kyseiseltä tililtä.',
'Tfa_Guide_Open_Users' => 'Avaa Käyttäjät',
'Tfa_Guide_Mobile_Title' => 'Mobiilisovellus ja API',
'Tfa_Guide_Mobile_Text' => 'Mobiilisovellus ja API-tunnisteen päätepiste kysyvät samaa koodia. Jos 2FA vaaditaan käyttäjältä, joka ei ole vielä ottanut sitä käyttöön, hänen on kirjauduttava kerran verkkoselaimella tehdäkseen sen.',
'Tfa_Guide_Protect_Title' => 'Sisäänrakennettu suojaus',
'Tfa_Guide_Protect_1' => '5 väärää koodia estää kyseisen käyttäjän koodinsyötön 15 minuutiksi riippumatta yllä olevista lukitusasetuksista.',
'Tfa_Guide_Protect_2' => 'Kukin koodi ja kukin palautuskoodi toimii vain kerran.',
'Tfa_Guide_Protect_3' => 'Kun ”Kirjaa kirjautumistoiminta” on käytössä, väärät koodit näkyvät Kirjautumistoiminta-luettelossa merkinnällä ”Väärä 2FA-koodi”.',
'Tfa_Guide_Trouble_Title' => 'Vianmääritys',
'Tfa_Guide_Faq_Clock_Q' => '”Koodi ei kelpaa” tuoreella koodilla',
'Tfa_Guide_Faq_Clock_A' => 'Puhelimen kello on todennäköisesti väärässä. Koodit riippuvat ajasta: aseta puhelimen päivämäärä ja aika automaattiseksi (verkkoaika) ja kokeile sitten seuraavaa koodia.',
'Tfa_Guide_Faq_Phone_Q' => 'Siirtyminen uuteen puhelimeen',
'Tfa_Guide_Faq_Phone_A' => 'Käytä joko todennussovelluksen omaa siirtotoimintoa tai poista 2FA käytöstä profiilissa ja ota se uudelleen käyttöön uudella puhelimella (jos se on pakollinen, pyydä sen sijaan järjestelmänvalvojaa nollaamaan se).',
'Tfa_Guide_Faq_Locked_Q' => '”Liian monta virheellistä koodia”',
'Tfa_Guide_Faq_Locked_A' => 'Odota näytetty aika (enintään 15 minuuttia) tai pyydä järjestelmänvalvojaa nollaamaan käyttäjän 2FA.',
'Tfa_Guide_Faq_Key_Q' => 'Kukaan 2FA:ta käyttävä ei pääse kirjautumaan palvelinsiirron jälkeen',
'Tfa_Guide_Faq_Key_A' => '2FA-salaisuudet on salattu .env-tiedoston APP_KEY-avaimella. Säilytä sama APP_KEY siirtäessäsi tai palauttaessasi sovellusta; jos se on muuttunut, järjestelmänvalvojan, jolla ei ole 2FA:ta, on nollattava asianomaiset käyttäjät.',
'Tfa_Guide_Button' => 'Opas',
'Tfa_Guide_Title' => 'Kaksivaiheisen tunnistautumisen opas',
'Sec_2fa_Pending' => 'Käyttöönotto kesken: :count',
'Sec_2fa_See_Who' => 'Näytä ketkä',
'Sec_2fa_Grace_Off' => 'Ei siirtymäaikaa — käyttöönotto seuraavalla kirjautumisella',
'Sec_2fa_Applied' => 'Uloskirjattuja käyttäjiä: :count.',
'Tfa_Guide_Rollout_Title' => 'Ota käyttöön kaikille käyttäjille',
'Tfa_Guide_Rollout_1' => 'Ota se ensin käyttöön omalle tilillesi (Profiili), jotta tunnet vaiheet.',
'Tfa_Guide_Rollout_2' => 'Kerro tiimillesi, mikä sovellus asennetaan ja että käyttöönotto vie kirjautumisen yhteydessä noin minuutin.',
'Tfa_Guide_Rollout_3' => 'Ota käyttöön ”Vaadi kaksivaiheinen tunnistautuminen”, jätä ”Vaaditaan rooleilta” tyhjäksi (= kaikki käyttäjät) ja valitse halutessasi siirtymäaika. Napsauta Lähetä.',
'Tfa_Guide_Rollout_4' => 'Napsauta ”Kirjaa ulos käyttäjät ilman 2FA:ta”, jotta jo kirjautuneet ottavat sen käyttöön nyt eivätkä vasta jollakin myöhemmällä kirjautumisella. Sinä pysyt kirjautuneena.',
'Tfa_Guide_Rollout_5' => 'Seuraa edistymistä tämän kortin laskurista tai Käyttäjät-sivun suodattimella ”Vaatii käyttöönoton”.',
'Tfa_Guide_Rollout_Note' => 'Siirtymäajan aikana käyttöönottonäkymässä näkyy ”Muistuta myöhemmin” määräaikaan asti; sen jälkeen käyttöönotto on pakollinen kirjautumiseen.',
'Tfa_Guide_Customers_Title' => 'Asiakastilit (kauppa ja asiakasportaali)',
'Tfa_Guide_Customers_Text' => 'Myös asiakkaat voivat suojata omat tilinsä. Se on vapaaehtoinen jokaiselle asiakkaalle eikä sitä koskaan pakoteta: ota se käyttöön kohdassa Kaupan asetukset → Rekisteröitymisen käyttöoikeudet (verkkokauppa) ja Asiakasportaali → Portaalin asetukset (asiakasportaali).',
'Tfa_Guide_Customers_1' => 'Asiakkaat ottavat sen käyttöön kohdasta Oma tili (kauppa) tai Profiili (portaali).',
'Tfa_Guide_Customers_2' => 'He valitsevat sähköpostilla lähetettävän koodin — helpoin, sovellusta ei tarvita — tai todennussovelluksen palautuskoodeineen.',
'Tfa_Guide_Customers_3' => 'Sähköpostikoodit edellyttävät toimivia sähköpostiasetuksia (Asetukset → Sähköpostiasetukset). Ne vanhenevat 10 minuutin kuluttua.',
'Tfa_Guide_Customers_4' => 'Kun asetus myöhemmin poistetaan käytöstä, uusia käyttöönottoja ei voi enää tehdä; asiakkailta, jotka jo käyttävät sitä, kysytään edelleen koodia, ja he voivat poistaa sen itse käytöstä.',
'Tfa_Required_Grace_Notice' => 'Järjestelmänvalvojasi edellyttää kaksivaiheista tunnistautumista. Voit lykätä sitä kirjautuessasi :date asti; sen jälkeen käyttöönotto on pakollinen.',
