'Sec_2fa_Grace' => 'Siirtymäaika',
'Sec_2fa_Grace_Help' => 'Käyttäjät voivat valita käyttöönottonäkymässä ”Muistuta myöhemmin” määräaikaan asti, jotta kenenkään työvuoro ei keskeydy. Lasketaan siitä, kun vaatimus otettiin käyttöön.',
